mapper.select:
SELECT * FROM (
    SELECT A.*, ROWNUM AS RNUM FROM (
        SELECT X.* FROM (
            SELECT GROUP_ID, GROUP_NM, GROUP_DESC, USE_YN, REG_ID, REG_DT
                FROM TB_CONTACT_GROUP
                ORDER BY GROUP_ID DESC
        ) X

    ) A WHERE ROWNUM <= #{offset} + #{size}
) WHERE RNUM > #{offset}
